	(68,0,'rss_a55d4e4c980f9c0711ba50c6baab8e97','Y',1,'O:9:\"magpierss\":17:{s:6:\"parser\";i:0;s:12:\"current_item\";a:0:{}s:5:\"items\";a:0:{}s:7:\"channel\";a:11:{s:5:\"title\";s:52:\"Blog reactions to http://www.jason-preston.com/potd/\";s:4:\"link\";s:73:\"http://technorati.com/search/http%3A%2F%2Fwww.jason-preston.com%2Fpotd%2F\";s:11:\"description\";s:71:\"Blog posts linking to http://www.jason-preston.com/potd/ on Technorati.\";s:7:\"pubdate\";s:31:\"Fri, 09 May 2008 11:10:45 -0700\";s:9:\"generator\";s:15:\"Technorati v1.0\";s:9:\"webmaster\";s:43:\"support@technorati.com (Technorati Support)\";s:4:\"docs\";s:37:\"http://blogs.law.harvard.edu/tech/rss\";s:3:\"ttl\";s:2:\"60\";s:4:\"tapi\";a:3:{s:6:\"result\";s:5:\"\n    \";s:10:\"result_url\";s:34:\"http://www.jason-preston.com/potd/\";s:19:\"result_inboundlinks\";s:1:\"0\";}s:6:\"result\";s:10:\"\n    \n    \";s:7:\"tagline\";s:71:\"Blog posts linking to http://www.jason-preston.com/potd/ on Technorati.\";}s:9:\"textinput\";a:0:{}s:5:\"image\";a:3:{s:3:\"url\";s:50:\"http://static.technorati.com/pix/logos/logo_sm.gif\";s:5:\"title\";s:15:\"Technorati logo\";s:4:\"link\";s:73:\"http://technorati.com/search/http%3A%2F%2Fwww.jason-preston.com%2Fpotd%2F\";}s:9:\"feed_type\";s:3:\"RSS\";s:12:\"feed_version\";s:3:\"2.0\";s:5:\"stack\";a:0:{}s:9:\"inchannel\";b:0;s:6:\"initem\";b:0;s:9:\"incontent\";b:0;s:11:\"intextinput\";b:0;s:7:\"inimage\";b:0;s:13:\"current_field\";s:0:\"\";s:17:\"current_namespace\";b:0;s:19:\"_CONTENT_CONSTRUCTS\";a:6:{i:0;s:7:\"content\";i:1;s:7:\"summary\";i:2;s:4:\"info\";i:3;s:5:\"title\";i:4;s:7:\"tagline\";i:5;s:9:\"copyright\";}}',20,8,'',1,'no'),
